//---ECC register wr logic

  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          passwd  <= 32'h0badbeef;
      end 
      else if (hwr_PASSWORD) begin
          passwd  <= pwdata[31:0];
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          parity_invert  <= 1'b0;
          parity_fault_injection  <= 4'b0;
          lockstep_fault_injection  <= 2'b0;
          fault_injection_en  <= 1'b0;
          parity_decoder_enable  <= 1'b0;
      end 
      else if (hwr_FUSA_CTRL) begin
          parity_invert  <= pwdata[12];
          parity_fault_injection  <= pwdata[11:8];
          lockstep_fault_injection  <= pwdata[3:2];
          fault_injection_en  <= pwdata[1];
          parity_decoder_enable  <= pwdata[0];
      end
      else if(parity_invert_d) begin
          parity_invert <= 1'b0;
      end
            
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          pd_top_noc_idlereq_time_out_mask  <= 1'b1;
          pd_top_bisr_done_time_out_mask  <= 1'b1;
          pd_top_bisr_busy_time_out_mask  <= 1'b1;
          pd_top_pwr_off_time_out_mask  <= 1'b1;
          top_pmu_signal_chk_err_mask  <= 1'b1;
          lockstep_err_mask  <= 1'b1;
          parity_err_mask  <= 1'b1;
      end 
      else if (hwr_MIssionIntMask0) begin
          pd_top_noc_idlereq_time_out_mask  <= pwdata[6];
          pd_top_bisr_done_time_out_mask  <= pwdata[5];
          pd_top_bisr_busy_time_out_mask  <= pwdata[4];
          pd_top_pwr_off_time_out_mask  <= pwdata[3];
          top_pmu_signal_chk_err_mask  <= pwdata[2];
          lockstep_err_mask  <= pwdata[1];
          parity_err_mask  <= pwdata[0];
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          pd_top_noc_idlereq_time_out_status  <= 1'b0;
      end
      else if (pd_top_noc_idlereq_time_out_status_wr) begin
          pd_top_noc_idlereq_time_out_status  <= pd_top_noc_idlereq_time_out_status_in;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[6]) begin
          pd_top_noc_idlereq_time_out_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatus0) begin
          if (pwdata[6] == 1'b1) begin
              pd_top_noc_idlereq_time_out_status  <= ~pwdata[6];
          end
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          pd_top_bisr_done_time_out_status  <= 1'b0;
      end
      else if (pd_top_bisr_done_time_out_status_wr) begin
          pd_top_bisr_done_time_out_status  <= pd_top_bisr_done_time_out_status_in;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[5]) begin
          pd_top_bisr_done_time_out_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatus0) begin
          if (pwdata[5] == 1'b1) begin
              pd_top_bisr_done_time_out_status  <= ~pwdata[5];
          end
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          pd_top_bisr_busy_time_out_status  <= 1'b0;
