      else if (pd_top_pwr_off_time_out_status_wr) begin
          pd_top_pwr_off_time_out_status  <= pd_top_pwr_off_time_out_status_in;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[3]) begin
