  begin
      if (!presetn) begin
          top_pmu_signal_chk_err_status  <= 1'b0;
      end
      else if (top_pmu_signal_chk_err_status_wr) begin
          top_pmu_signal_chk_err_status  <= top_pmu_signal_chk_err_status_in;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[2]) begin
          top_pmu_signal_chk_err_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatus0) begin
