              top_pmu_signal_chk_err_status  <= ~pwdata[2];
          end
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          lockstep_err_status  <= 1'b0;
      end
      else if (lockstep_err_status_wr) begin
          lockstep_err_status  <= lockstep_err_status_in;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[1]) begin
          lockstep_err_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatus0) begin
          if (pwdata[1] == 1'b1) begin
              lockstep_err_status  <= ~pwdata[1];
          end
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          parity_err_status  <= 1'b0;
      end
      else if (reg_parity_error) begin
          parity_err_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatusSet0 & pwdata[0]) begin
          parity_err_status  <= 1'b1;
      end
      else if (hwr_MIssionIntStatus0) begin
          if (pwdata[0] == 1'b1) begin
              parity_err_status  <= ~pwdata[0];
          end
      end
  end
        
  always @(posedge pclk or negedge presetn)
  begin
      if (!presetn) begin
          parity_invert_d <= 1'b0;
      end

      else if(parity_invert) begin
          parity_invert_d <= parity_invert;
      end
      else if(parity_invert_d) begin
          parity_invert_d <= 1'b0;
      end
  end
            
assign parity_decoder_bypass = ~parity_decoder_enable;

//--- ECC process logic
genvar i;
genvar j;
generate
  for (i=0; i<32; i=i+1) begin: reg_data_bank
    for (j=0; j<32; j=j+1) begin: in_bank_data_l
      assign reg_enc_data_in[i][j] = 
             reg_data_res[i][j] ? 1'b0                :
             reg_data_hw[i][j]  ? hw_wdata[i][j]      :
             reg_data_w1s[i][j] ? pwdata[j]  | reg_enc_data[i][j]:
             reg_data_w1c[i][j] ? ~pwdata[j] & reg_enc_data[i][j]:
             reg_data_w0s[i][j] ? ~pwdata[j] | reg_enc_data[i][j]:
             reg_data_w0c[i][j] ? pwdata[j]  & reg_enc_data[i][j]:
             reg_data_wt[i][j]  ? ~reg_enc_data[i][j] :
             reg_data_wr[i][j]  ? pwdata[j]           :
             reg_data_rc[i][j]  ? 1'b0                :
		                          reg_enc_data[i][j]  ; 
    end

    assign reg_parity_update[i] = ~fault_injection_en &((|reg_data_w1s[i])| 
                                                       (|reg_data_w1c[i]) |
                                                       (|reg_data_w0s[i]) |
                                                       (|reg_data_w0c[i]) |
                                                       (|reg_data_wt[i] ) |
                                                       (|reg_data_rc[i] ) |
                                                       (|reg_data_wr[i] ) |
                                                       (|reg_data_hw[i] ))
                                | fault_injection_en & (|reg_data_wr[i] )
                                | parity_invert; 


  end
endgenerate


