// register_error
 assign reg_parity_error = (parity_invert)? reg_parity_error_and : reg_parity_error_or;
  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_noc_idlereq_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_noc_idlereq_time_out_err <= ~pd_top_noc_idlereq_time_out_mask & pd_top_noc_idlereq_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_bisr_done_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_bisr_done_time_out_err <= ~pd_top_bisr_done_time_out_mask & pd_top_bisr_done_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_bisr_busy_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_bisr_busy_time_out_err <= ~pd_top_bisr_busy_time_out_mask & pd_top_bisr_busy_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        pd_top_pwr_off_time_out_err <= 1'b0; 
   end 
   else begin
        pd_top_pwr_off_time_out_err <= ~pd_top_pwr_off_time_out_mask & pd_top_pwr_off_time_out_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        top_pmu_signal_chk_err <= 1'b0; 
   end 
   else begin
        top_pmu_signal_chk_err <= ~top_pmu_signal_chk_err_mask & top_pmu_signal_chk_err_status; 
   end
end

  
  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        lockstep_err <= 1'b0; 
   end 
   else begin
        lockstep_err <= ~lockstep_err_mask & lockstep_err_status; 
   end
end


// mission_int, include SW parity_invert injection

  always @(posedge pclk or negedge presetn)
  begin
      if(!presetn) begin
        mission_int <= 1'b0; 
   end 
   else begin
        mission_int <= ~parity_err_mask & parity_err_status; 
   end
end



